package com.codegym.service;
import com.codegym.model.Product; import java.util.*;
public class ProductServiceImpl implements ProductService { private static final Map<Integer,Product> products=new LinkedHashMap<>(); static {products.put(1,new Product(1,"Laptop Dell",1500,"Laptop văn phòng","Dell"));products.put(2,new Product(2,"Điện thoại iPhone",1200,"Điện thoại thông minh","Apple"));products.put(3,new Product(3,"Tai nghe Bluetooth",80,"Tai nghe không dây","Sony"));products.put(4,new Product(4,"Bàn phím cơ",100,"Bàn phím chơi game","Logitech"));} public List<Product> findAll(){return new ArrayList<>(products.values());} public List<Product> searchByName(String name){String q=name==null?"":name.trim().toLowerCase();if(q.isEmpty())return findAll();return products.values().stream().filter(p->p.getName().toLowerCase().contains(q)).toList();} public void save(Product p){products.put(p.getId(),p);} public Product findById(int id){return products.get(id);} public void update(int id,Product p){p.setId(id);products.put(id,p);} public void remove(int id){products.remove(id);} }
